/* Rodent V browser transport. The matching Go runtime is generated by build.mjs. */
let failed = false;
let quitting = false;
let manifest;
const base = new URL('./dist/', self.location.href);
const decoder = new TextDecoder();
let stdout = '';
const outputTail = [];

function fail(error) {
    if(failed || quitting) return;
    failed = true;
    postMessage({ type: 'error', message: error?.message || String(error) });
}

function recordOutput(line) {
    if(!line) return;
    outputTail.push(line);
    if(outputTail.length > 20) outputTail.shift();
    postMessage(line);
}

self.rodentReadAsset = async (name, callback) => {
    try {
        const asset = Object.hasOwn(manifest.assets, name) && manifest.assets[name];
        if(!asset) throw new Error(`Unknown bundled asset: ${name}`);
        const response = await fetch(new URL(`assets/${name}`, base), { signal: AbortSignal.timeout(30000) });
        if(!response.ok) throw new Error(`Could not load ${name}: HTTP ${response.status}`);
        const bytes = new Uint8Array(await response.arrayBuffer());
        const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', bytes));
        const hash = Array.from(digest, byte => byte.toString(16).padStart(2, '0')).join('');
        if(bytes.length !== asset.size || hash !== asset.sha256) throw new Error(`Invalid bundled asset: ${name}`);
        callback(null, bytes);
    } catch(error) {
        fail(error);
        callback(error.message, null);
    }
};

self.onmessage = ({ data }) => {
    if(failed) return;
    try {
        if(typeof data !== 'string' || /[\r\n\0]/.test(data)) throw new Error('Expected one UCI command.');
        if(typeof self.rodentCommand !== 'function') throw new Error('Engine is not ready.');
        if(data.trim() === 'quit') quitting = true;
        if(!self.rodentCommand(data)) throw new Error('UCI command queue is full.');
    } catch(error) {
        fail(error);
    }
};

(async () => {
    importScripts(new URL('wasm_exec.js', base).href);
    self.fs.writeSync = (fd, buffer) => {
        stdout += decoder.decode(buffer, { stream: true });
        let newline;
        while((newline = stdout.indexOf('\n')) !== -1) {
            const line = stdout.slice(0, newline).trimEnd();
            stdout = stdout.slice(newline + 1);
            recordOutput(line);
        }
        return buffer.length;
    };
    const response = await fetch(new URL('build-info.json', base), { signal: AbortSignal.timeout(30000) });
    if(!response.ok) throw new Error(`Could not load build manifest: HTTP ${response.status}`);
    manifest = await response.json();
    const networkSize = new URL(self.location.href).searchParams.get('networkSize');
    const binary = manifest.binaries[networkSize];
    if(!binary) throw new Error(`Unsupported network size: ${networkSize}`);
    const wasm = await fetch(new URL(binary.file, base), { signal: AbortSignal.timeout(60000) });
    if(!wasm.ok) throw new Error(`Could not load WebAssembly: HTTP ${wasm.status}`);
    const go = new Go();
    go.exit = code => {
        if(code !== 0) {
            const details = outputTail.join('\n').slice(-4000);
            fail(new Error(`Go runtime exited with code ${code}.${details ? `\n${details}` : ''}`));
        }
    };
    // Buffered instantiation also works on hosts with an incorrect WASM MIME type.
    const bytes = await wasm.arrayBuffer();
    const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', bytes));
    const hash = Array.from(digest, byte => byte.toString(16).padStart(2, '0')).join('');
    if(hash !== binary.sha256) throw new Error('WebAssembly does not match the build manifest.');
    const { instance } = await WebAssembly.instantiate(bytes, go.importObject);
    await go.run(instance);
    if(!quitting) fail(new Error('Engine exited unexpectedly.'));
})().catch(fail);
